xml.Script:
        clYellow    := 'FFFF00';
        clBlue      := '0000A0';
        clOrange    := 'FF6000';
        clRed       := 'FF0000';
        clGreen     := '008000';
        clWhite     := 'FFFFFF';
        clViolett   := '800080';
        clLightBlue := '2868FF';

        R := 0.65;

        x0 := R * sqrt(4 - 2 * sqrt(2));
        Vz := R * (3 - 2 * sqrt(2));

        for i := 0 to 7 do begin
            x[i] := x0 * cos(Pi / 4 * (i + 0.5));
            y[i] := x0 * sin(Pi / 4 * (i + 0.5));
            z[i] := Vz;
            az[i] := -R;
            if i mod 2 = 0 then begin
                z[i] := -Vz;
                az[i] := R;
            end;
        end;

        D := R * 0.3; // sqrt((7 - 4 * sqrt(2)) / 17) * 1.08

        A1 := ArcCos(sqrt(2) / 2 - 1 / 4); // 62.8 degs
        A2 := ArcCos((sqrt(2) - 4) / 7); // 111.7 degs
        A3 := (2 * Pi - A1 ) / 2; // 148.6 degs
